import { clsx as __twl_clsx, twMerge as __twl_twMerge } from 'twl';

const override = 'px-8'

// The merge cannot happen until the interpolation has a value, so the call
// stays - but the template around it is already folded.
export const result = __twl_twMerge(`px-2 py-1 flex items-center ${__twl_clsx(override)}`)
